36	func (s *healthCheckStep) Run(ctx context.Context, log logging.Logger, obj *advisor.CheckSpec, i any) ([]advisor.CheckReportFailure, error) {
37		ds, ok := i.(*datasources.DataSource)
38		if !ok {
39			return nil, fmt.Errorf("invalid item type %T", i)
40		}
41	
42		// Health check execution
43		resp, err := s.HealthChecker.CheckHealth(ctx, ds)
44		if err != nil || (resp != nil && resp.Status != backend.HealthStatusOk) {
45			// Unable to check health check
46			log.Error("Failed to run health check", "datasource_uid", ds.UID, "error", err)
47			if errors.Is(err, plugins.ErrMethodNotImplemented) || errors.Is(err, plugins.ErrPluginUnavailable) {
48				// The plugin does not support backend health checks
49				return nil, nil
50			}
51			// For other errors (including ErrPluginNotRegistered from GetWithDataSource),
52			// we skip the health check step and let the missing plugin step handle it
53			if errors.Is(err, plugins.ErrPluginNotRegistered) {
54				// The plugin is not installed, handle this in the missing plugin step
55				return nil, nil
56			}
57			moreInfo := ""
58			if resp != nil {
59				moreInfo = fmt.Sprintf("Status: %s\nMessage: %s\nJSONDetails: %s", resp.Status, resp.Message, resp.JSONDetails)
60			}
61			return []advisor.CheckReportFailure{checks.NewCheckReportFailureWithMoreInfo(
62				advisor.CheckReportFailureSeverityHigh,
63				s.ID(),
64				ds.Name,
65				ds.UID,
66				[]advisor.CheckErrorLink{
67					{
68						Message: "Fix me",
69						Url:     fmt.Sprintf("/connections/datasources/edit/%s", ds.UID),
70					},
71				},
72				moreInfo,
73			)}, nil
74		}
75		return nil, nil
76	}
